    """Run a git command from the project root and return stdout."""
    try:
        result = subprocess.run(
            ["git", *args],
            cwd=PROJECT_ROOT,
            text=True,
            capture_output=True,
            check=False,
            timeout=GIT_TIMEOUT_S,
        )
    except subprocess.TimeoutExpired as exc:
        if check:
            raise RuntimeError(
                f"git command timed out after {GIT_TIMEOUT_S}s: git {' '.join(args)}"
            ) from exc
        return ""
